class IndependentOwnedCleanup(unittest.TestCase):
    """A refused resource must not prevent cleanup of later independently owned resources."""

    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="godseye-services-test-")
        self.services = SERVICES.Services.__new__(SERVICES.Services)
        self.services.root = Path(self.temporary.name).resolve()
        self.services.pg_bin = self.services.root / "fixture-pg-bin"
        self.services.pg_env = {}
        self.state = {"databases": [
            {"name": "d0", "port": 41001},
            {"name": "d1", "port": 41002, "redisPort": 42001},
            {"name": "d2", "port": 41003, "redisPort": 42002},
        ]}

    def tearDown(self):
        self.temporary.cleanup()

    def test_T_E06_P04_refused_first_redis_identity_still_stops_all_owned_postgres_and_later_redis(self):
        visited_redis = []
        def redis_live(cell):
            visited_redis.append(cell["name"])
            if cell["name"] == "d1":
                raise RuntimeError("fixture foreign Redis identity")
            return True
        with patch.object(self.services, "redis_live", side_effect=redis_live), \
             patch.object(self.services, "redis_cli", return_value="") as redis_stop, \
             patch.object(self.services, "pg_live", return_value=True), \
             patch.object(SERVICES, "run", return_value="") as postgres_stop:
            with self.assertRaises(RuntimeError):
                self.services.stop(self.state)
        self.assertEqual(visited_redis, ["d1", "d2"])
        self.assertEqual([call.args[0]["name"] for call in redis_stop.call_args_list], ["d2"])
        self.assertEqual(
            [Path(call.args[0][call.args[0].index("-D") + 1]).parent.name
             for call in postgres_stop.call_args_list], ["d0", "d1", "d2"]
        )

    def test_T_E06_P04_failed_redis_shutdown_does_not_skip_its_postgres_or_later_resources(self):
        def redis_cli(cell, *_args):
            if cell["name"] == "d1":
                raise RuntimeError("fixture shutdown refused")
            return ""
        with patch.object(self.services, "redis_live", return_value=True), \
             patch.object(self.services, "redis_cli", side_effect=redis_cli) as redis_stop, \
             patch.object(self.services, "pg_live", return_value=True), \
             patch.object(SERVICES, "run", return_value="") as postgres_stop:
            with self.assertRaises(RuntimeError):
                self.services.stop(self.state)
        self.assertEqual([call.args[0]["name"] for call in redis_stop.call_args_list], ["d1", "d2"])
        self.assertEqual(postgres_stop.call_count, 3)

    def test_T_E06_P04_foreign_postgres_is_never_stopped_while_later_owned_postgres_is_cleaned(self):
        def pg_live(cell):
            if cell["name"] == "d1":
                raise RuntimeError("fixture foreign PostgreSQL identity")
            return True
        with patch.object(self.services, "redis_live", return_value=False), \
             patch.object(self.services, "pg_live", side_effect=pg_live), \
             patch.object(SERVICES, "run", return_value="") as postgres_stop:
            with self.assertRaises(RuntimeError):
                self.services.stop(self.state)
        self.assertEqual(
            [Path(call.args[0][call.args[0].index("-D") + 1]).parent.name
             for call in postgres_stop.call_args_list], ["d0", "d2"]
        )


